def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    fill = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == bg and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if any(y == 0 or y == h-1 or x == 0 or x == w-1 for y, x in comp):
                continue
            min_y = min(y for y, x in comp)
            max_y = max(y for y, x in comp)
            min_x = min(x for y, x in comp)
            max_x = max(x for y, x in comp)
            if len(comp) == (max_y - min_y + 1) * (max_x - min_x + 1):
                fill.update(comp)

    return [[4 if (r, c) in fill else grid[r][c] for c in range(w)]
            for r in range(h)]
